const text = ($input.item.json.text || '').replace(/\s+/g, ' ');
const grab = (re) => { const m = text.match(re); return m ? m[1].trim() : ''; };
const invoiceNumber = grab(/(?:invoice|inv|bill)\s*(?:no\.?|number|#)?\s*[:#]?\s*([A-Z0-9][A-Z0-9\-\/]{2,})/i);
const rawTotal = grab(/(?:total|amount due|grand total|balance due)\s*[:]?\s*[^0-9]{0,4}([0-9][0-9,]*\.?[0-9]{0,2})/i);
const issuedOn = grab(/(?:date|issued|invoice date)\s*[:]?\s*([0-9]{1,2}[\/\-. ][A-Za-z0-9]{2,9}[\/\-. ][0-9]{2,4})/i);
return { json: { invoiceNumber, issuedOn, total: rawTotal ? Number(rawTotal.replace(/,/g, '')) : null, textFound: text.length > 40 } };
